        "text": "Hasta hafif persistan astım öyküsü olmasına rağmen migren profilaksisi ve hipertansiyon kontrolü için propranolol kullanmaya başlamıştır. İlk birkaç dozdan sonra göğüste sıkışma, kuru öksürük ve hışıltılı solunum fark etmiş; albuterol inhalerine yanıtı önceki ataklarına göre daha zayıf olmuştur. Ateş, balgam veya göğüs ağrısı tariflememektedir. Daha önce beta-bloker kullanmamış, yeni antibiyotik veya NSAİİ maruziyeti bildirmemiştir."
