        "text": "Yakınları hastanın yaklaşık 3-4 saat önce normal dozunun üzerinde çok sayıda propranolol tableti aldığını belirtmektedir. İlacı migren profilaksisi ve hipertansiyon için düzenli kullandığı, son günlerde ek kalsiyum kanal blokeri veya digoksin başlamadığı öğrenilmiştir. Acile getirildiğinde belirgin halsizlik, baş dönmesi ve uykuya eğilim vardır. Kusma ya da travma öyküsü alınmaz; evde başka ilaç kutusu bulunmamıştır."
